<template><view class="page"><view class="head row"><view><text class="eyebrow">企业运营</text><text class="title">商品管理</text></view><view class="primary-btn add" @tap="create">新增 +</view></view><view v-if="list.length" class="product-list"><view v-for="item in list" :key="item._id" class="product-card card"><view class="product-top"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><view v-else class="product-image placeholder">◇</view><view class="product-main"><text class="product-name">{{item.name}}</text><text class="sku">SKU：{{item.sku||'TB-'+item._id.slice(-6).toUpperCase()}}</text><text class="carbon">♧ {{item.carbonReduction||0}}kg CO₂e</text></view><text class="more">⋮</text></view><view class="divider"></view><view class="stock-row"><view><text class="stock-label">库存</text><text :class="['stock-value',item.stock<20?'low':'']">{{item.stock}} 件 <text v-if="item.stock<20">（Low）</text></text></view><view class="actions"><view class="outline-btn edit" @tap="editStock(item)">编辑</view><view class="delete-btn" @tap="deleteProduct(item)">删除</view></view></view></view></view><view v-else class="empty card">暂无商品，请点击右上角新增</view><BottomNav role="enterprise" active="products"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';import {callCloud} from '../../common/cloud.js';import {toast} from '../../common/mock.js';export default{components:{BottomNav},data(){return{list:[]}},async onShow(){this.load()},methods:{async load(){try{const result=await callCloud('product-list',{enterpriseId:uni.getStorageSync('user_session')?.id||'enterprise_demo'});this.list=result.data||[]}catch(error){this.list=[];toast(error.message||'商品加载失败')}},create(){uni.navigateTo({url:'/pages/enterprise/product-create'})},editStock(item){uni.showModal({title:'编辑库存',editable:true,placeholderText:String(item.stock),success:async res=>{if(!res.confirm||res.content==='')return;try{const result=await callCloud('product-stock-update',{productId:item._id,stock:Number(res.content),enterpriseId:uni.getStorageSync('user_session')?.id||'enterprise_demo'});item.stock=result.stock;toast('库存已更新')}catch(error){toast(error.message||'库存更新失败')}}})},deleteProduct(item){uni.showModal({title:'删除商品',content:'确定要删除该商品吗？删除后个人端商城将不再展示。',success:async res=>{if(!res.confirm)return;try{await callCloud('product-delete',{productId:item._id,enterpriseId:uni.getStorageSync('user_session')?.id||'enterprise_demo'});this.list=this.list.filter(x=>x._id!==item._id);toast('商品已删除')}catch(error){toast(error.message||'删除失败')}}})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.add{min-height:60rpx;padding:0 20rpx;font-size:22rpx}.product-card{margin-bottom:18rpx;padding:22rpx}.product-top{display:flex;align-items:center}.product-image{width:150rpx;height:120rpx;margin-right:20rpx;border-radius:14rpx;background:#eaf1ec}.placeholder{display:flex;align-items:center;justify-content:center;color:#6e7d72;font-size:48rpx}.product-main{flex:1}.product-name{display:block;font-size:29rpx;font-weight:700}.sku{display:block;margin-top:8rpx;color:#66736b;font-size:22rpx}.carbon{display:inline-block;margin-top:10rpx;padding:6rpx 14rpx;border-radius:20rpx;background:#e5f4e9;color:#347c55;font-size:20rpx}.more{align-self:flex-start;color:#6d7a6e;font-size:36rpx}.divider{height:1rpx;margin:20rpx 0;border-top:1rpx solid #e8eeea}.stock-row{display:flex;align-items:center;justify-content:space-between}.stock-label{display:block;color:#66736b;font-size:21rpx}.stock-value{display:block;margin-top:6rpx;font-size:27rpx}.stock-value.low{color:#c0392b}.stock-value.low text{font-size:21rpx}.actions{display:flex;gap:12rpx}.edit,.delete-btn{min-width:100rpx;min-height:62rpx;padding:0 16rpx}.delete-btn{display:flex;align-items:center;justify-content:center;border:2rpx solid #c0392b;border-radius:34rpx;color:#c0392b;font-size:24rpx}.empty{text-align:center}</style>
